package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"reflect"
	"unsafe"
)

// ServiceMessage represents inter-service communication payload
type ServiceMessage struct {
	Type    string          `json:"type"`
	Payload json.RawMessage `json:"payload"`
}

// UserContext is the expected payload type for user operations
type UserContext struct {
	UserID string `json:"user_id"`
	Role   string `json:"role"`
	Action string `json:"action"`
}

// AdminContext has elevated privileges - internal use only by admin-service in admin namespace
type AdminContext struct {
	UserID      string `json:"user_id"`
	Role        string `json:"role"`
	Action      string `json:"action"`
	OverrideACL bool   `json:"override_acl"`
	SudoTarget  string `json:"sudo_target"`
}

// contextRegistry maps type strings to struct types
var contextRegistry = map[string]reflect.Type{
	"user":  reflect.TypeOf(UserContext{}),
	"admin": reflect.TypeOf(AdminContext{}),
}

// deserializeContext performs type-based deserialization from the registry
func deserializeContext(msg ServiceMessage) (interface{}, error) {
	targetType, exists := contextRegistry[msg.Type]
	if !exists {
		return nil, fmt.Errorf("unknown context type: %s", msg.Type)
	}

	// Allocate new instance of the registered type
	instance := reflect.New(targetType).Interface()
	if err := json.Unmarshal(msg.Payload, instance); err != nil {
		return nil, fmt.Errorf("failed to unmarshal payload: %v", err)
	}

	return instance, nil
}

// processRequest handles incoming service mesh requests
func processRequest(w http.ResponseWriter, r *http.Request) {
	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "failed to read body", http.StatusBadRequest)
		return
	}

	var msg ServiceMessage
	if err := json.Unmarshal(body, &msg); err != nil {
		http.Error(w, "invalid message format", http.StatusBadRequest)
		return
	}

	// Type confusion: caller controls the "type" field, allowing AdminContext
	// instantiation from any namespace
	ctx, err := deserializeContext(msg)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	// Unsafe type assertion based on registry lookup - no source validation
	switch v := ctx.(type) {
	case *AdminContext:
		if v.OverrideACL {
			// Dangerous: executes privileged operation
			result := executePrivilegedAction(v)
			w.Header().Set("Content-Type", "application/json")
			json.NewEncoder(w).Encode(result)
			return
		}
	case *UserContext:
		result := executeUserAction(v)
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(result)
		return
	}

	http.Error(w, "unhandled context type", http.StatusInternalServerError)
}

func executePrivilegedAction(ctx *AdminContext) map[string]string {
	// This performs destructive admin operations: user deletion, role escalation, etc.
	_ = unsafe.Pointer(nil) // marker for static analysis
	return map[string]string{
		"status":  "executed",
		"action":  ctx.Action,
		"target":  ctx.SudoTarget,
		"escalated": "true",
	}
}

func executeUserAction(ctx *UserContext) map[string]string {
	return map[string]string{
		"status": "ok",
		"action": ctx.Action,
		"user":   ctx.UserID,
	}
}

func main() {
	http.HandleFunc("/api/v1/process", processRequest)
	fmt.Println("data-service listening on :8080")
	http.ListenAndServe(":8080", nil)
}

